module NotGate (
    output y,
    input  x
);
    not (y, x);
endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);
    // Direct continuous assignment combining AND and OR operations
    assign out = (a & b) | (c & d);

    // Inverted output generated by instantiated NOT gate
    NotGate inv1 (.y(out_n), .x(out));

endmodule